import{_ as s,O as i,o as a,c as r,a as o,i as n,f as d}from"./chunks/framework.fmIt2z2h.js";const x=JSON.parse('{"title":"D.11　中国思想与实践传统的现代转译","description":"","frontmatter":{"title":"D.11　中国思想与实践传统的现代转译","xkChars":686,"xkLessons":{"D.11":{"title":"D.11　中国思想与实践传统的现代转译","lead":"传统思想可以启发今天的问题，也可以被批评和发展。关键是分清原文说了什么、历史制度怎样运行，以及今天选择怎样重译；不能因为找到相似词语，就说现代框架在古代已经完整存在。","explanation":["原文定位：第4689—4704行；原文锚点 section-d-11；短引文：‘现代转译可以选择平等和独立复核，却须承认这是当前规范选择，不能倒写成古人的全部原义。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","儒家的角色、修养与批评，道家的自然、齐物与有限知识，墨家的兼爱、非攻与功用，法家的规则、组织与权势，兵家的情势、信息与时机，提供不同问题入口。这些是宽泛导航而非学派全貌。每次借用都应回到具体篇章、对象和历史条件，保留内部张力，不能把不同传统压成现代框架的一组同义词。","角色责任既可能支撑长期照护，也可能被用来征用某些人的劳动。判断需要看谁能提出需要、谁承担、能否拒绝、负担如何分配，而不是从孝、仁或责任这些好词自动推出良好结果。同一个角色安排中，持续照护与不公平负担可能同时存在，评价不能择一抹去另一面。","可预测规则能限制一些局部任意，却可能与中心权力缺少制约并存。文本规定办事程序，不等于规则制定者也受独立监督；下属一视同仁执行，不等于所有群体都有同等资格或救济。必须分清规则可预期性、适用范围、最终裁量和异议能否改变结果，不能把所有有规则的组织都称为现代法治。","减少控制有时有助生活，但减少控制与撤掉必要支持不是同一件事。若把少干预理解为不再提供可用照护、公共条件或救济，可能只是把负担转嫁给弱势者。解释道家等思想的现代启发时，不能借一个不控制的口号直接证明撤支持合理，实际对象和后果仍要接受核查。","军事策略的有效性不构成向普通关系移植强制手段的许可。某种手段能获得战场优势，与是否适合亲密关系、工作沟通或公共治理，是不同规范问题。若借用情势分析和信息判断，应说明抽象保留了什么、舍弃了什么；不能把操纵和压制包装成所有关系通用的智慧。","真诚不保证事实正确，知道道理不保证拥有实施机会。一个人诚恳陈述可得到相应尊重，但事实仍需材料；一个人能复述原则，却可能缺资源、时间、权限或安全条件。把知识或修养当作行动已经可行，会错误地把环境约束改写成人格缺陷。","愿意听取意见与异议能安全改变决定需要分开。上位者态度亲切、公开称赞谏言，可以是态度材料；若提出者仍受惩罚、没有复核、错误决定不能改变，制度反馈并未因此得到证明。传统文本里的劝谏启发可以继续发展为现代独立复核，但不能倒说古文本已完整规定今天的参与权与程序保障。","库存增加只支持库存层面的变化。民众是否改善还涉及资格、实际领取、质量、使用条件和家庭内部控制。可以同时存在仓库物资增加、部分家庭未能领取或领取后无法使用。民本等规范语言可提出值得重视的目标，却不能替代资源实际到人的各个环节。","理学与心学、经世制度实践、周易时位解释及近现代转型，应分别处理义理、史实、方法启发和规范理由。通变带来的条件敏感性启发不自动接受占验前提；今天以平等或主体性重译旧文本，也不证明旧作者拥有完全相同的概念。兼容只是一项需要具体说明的关系，不能由框架单方面宣布并终止争论。","同一制度在资格、考试、授官和实际进入机会等维度可采取不同安排。考试题相同并不证明所有人有资格、资源或进入机会；某资格维度不同，也不意味着每个考试或授官环节都朝同方向有差别。规则文本支持规定内容，地方执行材料支持实施情况，当事人经历支持相应经验，三者不能互代或由一个推完整体。","十个入口依次是孔孟荀的仁礼角色、老庄、墨家兼爱非攻尚贤、法术势、孙子等兵家、宋明理学心学、经世民本制度地方实践、周易时位术数取舍、近现代转型及现代转译。最强反方认为现代重译必然背叛传统；回应是可以明确承认当代选择并接受批评。另一反方把古今完全等同，则会抹去历史差异。细读应允许连续性、断裂和规范发展同时被具体说明。"],"distinctions":[{"leftTitle":"原文义理","leftText":"具体文本中表达的问题与理由。","rightTitle":"现代转译","rightText":"为当前问题重新选择概念与规范，需明示新增部分。"},{"leftTitle":"规则可预测","leftText":"某些程序与处置可预期。","rightTitle":"权力受独立制约","rightText":"最终裁量及复核另需制度与实际材料。"},{"leftTitle":"愿意听取","leftText":"个人态度或姿态。","rightTitle":"异议安全改变决定","rightText":"还涉及无报复、有效复核与决策反馈。"},{"leftTitle":"库存增加","leftText":"仓储数量发生变化。","rightTitle":"民众处境改善","rightText":"还需资格领取质量与实际控制等中间环节。"},{"leftTitle":"单维相同或不同","leftText":"如考试安排相同或资格不同。","rightTitle":"制度整体平等","rightText":"各环节需逐项比较，不能从单维推出整体。"}],"boundaries":["不声称古代学派或制度是现代Xikari提前存在的完整版本。","传世文本转录支持文本表述，不独自证明对话实际发生、作者全部思想或制度实际成效。","不以传统权威取消当代平等、安全拒绝和独立复核的论证责任。","不将军事效率当作普通关系强制、欺骗或操纵的许可。","以下地方制度与库存均为教学设定，不补写未经原始材料核实的历史案例。"],"questions":["传统思想的现代转译为何要明说新增选择？","为什么规则可预测仍可能缺乏权力制约？","库存材料最直接支持什么？","借用军事策略需要保留什么边界？"],"diagramPath":"/reading-assets/S-D-11/figures/section-d-11.png","caseLinks":[{"title":"传世原典细读：《论语·子路》十三之十五","href":"https://zh.wikisource.org/w/index.php?title=論語/子路第十三&oldid=11118102"}],"caseNotes":[{"title":"传世原典细读：《论语·子路》十三之十五","text":"该章以定公问一言兴邦、丧邦展开，文本将“不善而莫之违”的情境列为危险。本讲借此提出坏判断无人能反对的核查问题；它是对传世文本具体论证的阅读，不证明记载对话的历史真实性，也不把文本解释为已经建立现代独立复核或平等参与制度。","sourceLabel":"传世原典公共转录，固定页面版本","sourceUrl":"https://zh.wikisource.org/w/index.php?title=論語/子路第十三&oldid=11118102","sourceLocator":"《论语·子路》第十三之十五整章；维基文库转录固定修订oldid=11118102","boundary":"已核本章完整上下问答；未作出土版本或历代注疏校勘，现代应用是作者明确追加的解释，不是古今概念等同。","href":"https://zh.wikisource.org/w/index.php?title=論語/子路第十三&oldid=11118102"}],"sourceRefs":[{"section":"D.11","start_line":4689,"end_line":4704,"startLine":4689,"endLine":4704}],"outputId":"section-d-11","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["定位具体原篇章及对象，分清传统内部差异，不用单一标签替全部历史。","分别核角色照护与征用、局部规则与中心制约、减少控制与必要支持。","把态度、事实正确、实施机会与制度反馈分开，军事效能不直接授权一般强制。","追踪资源到人的资格领取质量控制链，分项比较制度资格考试授官进入。","公开义理史实方法启发规范理由与现代新增选择，不倒写古人原义。"],"teachingExamples":[{"title":"原文教学例展开：仓储多了，谁真正得到？","text":"假想一地账面库存由100增至150份，每份可用物资按同一标准统计。可确认账面增加50份；若要判断家庭改善，仍要查资格、实际领取、物资质量及由谁控制使用。若实际领到的人仍只有原来一批，库存增长并不自动形成更多人的改善。","assumptions":"数字与地方完全虚构，只演示不同层面的证据链。","boundary":"不推断任何历史朝代救济政策，也不将库存账自动当实物盘点。"},{"title":"教学构造：相同试题不等整体机会相同","text":"假想制度对进入考试者使用同一试题，但报名资格只对部分人开放，且备考资源不同。可承认试题环节相同，同时保留资格与进入机会不等；不能反过来因为资格不同就断言试卷评分每一步必然差别对待。","assumptions":"纯制度比较构造，不对应实际科举制度的完整史实。","boundary":"历史结论需指定时期、地区和原始规则执行资料。"},{"title":"教学构造：爱听批评但无法复核","text":"假想负责人邀请意见且态度温和，但错误决定没有复核路径，提异议者担心后续报复。可记录听取姿态，不能据此称异议已安全进入决策。若今天新增独立复核与保护，应说明这是当前制度选择，不倒写成古代谏诤制度全部原义。","assumptions":"组织与行为均虚构。","boundary":"未开展实际治理干预，不判断任何真实负责人的品格。"},{"title":"教学构造：减少控制不等于撤掉帮助","text":"假想服务安排希望减少不必要限制，同时保留本人愿意使用的沟通和交通支持。若把减少控制误做取消所有支持，可能降低实际选择。需分项看哪些限制应减少、哪些条件仍构成能力，而不靠不干预口号代判。","assumptions":"非特定治疗或公共服务建议，条件性教学例。","boundary":"不从例子证明某一古代学派必然主张此安排。"}],"counterexamples":[{"identity":"constructed_boundary","text":"这份古文反对无人敢谏，所以已完整提出当代独立审查制度。","effect":"批评启发与现代制度规定不同，新增规范应明说。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"地方物资库存增加，所以每家生活都得到改善。","effect":"库存不能跳过资格领取质量与家庭控制链。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"考试试题相同，所以整套制度必然平等。","effect":"资格授官实际进入和资源条件仍需逐项核查。","sourceIds":["theory"]}],"questionAnswers":[{"question":"传统思想的现代转译为何要明说新增选择？","answer":"否则会把当代平等或复核观念倒写成古人完整原义，抹掉历史差异。","basis":"本节原文及上述公开推导"},{"question":"为什么规则可预测仍可能缺乏权力制约？","answer":"规则执行与规则制定者、最终裁量者是否受独立复核是不同层次。","basis":"本节原文及上述公开推导"},{"question":"库存材料最直接支持什么？","answer":"按材料可靠性支持账面或实物库存变化，不自动支持家庭实际改善。","basis":"本节原文及上述公开推导"},{"question":"借用军事策略需要保留什么边界？","answer":"有效性不提供一般关系中使用强制的许可，需另核对象规范和后果。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-11/figures/section-d-11.png","alt":"具体文本与历史条件，保留内部张力；角色照护与征用，规则与中心制约，分别检查；真诚不保证正确，知道不等于能做，听取不等于能复核；库存到生活，资格领取质量，实际控制须核；资格／考试／授官，实际进入机会，单维不代表整体；方法启发可保留，现代规范须明示，不倒写古人原义。作者依D.11绘制；库存制度为教学构造，原典文本不替代历史实践核查。","caption":"作者依D.11绘制；库存制度为教学构造，原典文本不替代历史实践核查。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换材料来自规则文本、执行记录或当事人经历，显示每种材料支持哪一层结论。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实原典文本作为思想史阅读对象；不把文本记述冒称已独立证实的历史事件或制度效果。"},"openQuestions":["未取得11.01—11.10全部原研究与版本材料，不能依据入口复原完整传统思想史。","原典仅核指定章转录，未核对话史实及所有古注异文。"],"taskId":"S-D-11","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4689—4704行；每节精确范围见sourceRefs","claim_support":["D.11：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"analects13-15","title":"论语·子路第十三：十三之十五","url":"https://zh.wikisource.org/w/index.php?title=論語/子路第十三&oldid=11118102","source_type":"primary","version_or_date":"维基文库固定修订11118102；页面显示2026-10-03编辑","locator":"十三之十五全章，固定修订11118102（原动态页行181—183）","claim_support":["该章关于一言兴邦丧邦及不善而无人反对的具体文本"],"limits":["公共传世文本转录，未作版本校勘；不证明对话史实、现代制度已存在或实践效果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-11/lecture.md","sourcesPath":"/reading-assets/S-D-11/sources.json","sourceSlicePath":"/reading-assets/S-D-11/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-11/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-11.md","filePath":"theory/appendix-d/d-11.md"}'),l={name:"theory/appendix-d/d-11.md"};function c(p,e,u,h,_,m){const t=i("SectionLesson");return a(),r("div",null,[e[0]||(e[0]=o("",1)),n(t,{section:"D.11"}),e[1]||(e[1]=d("div",{class:"theory-source"},null,-1))])}const g=s(l,[["render",c]]);export{x as __pageData,g as default};
